recipes.code:
{
  "inputs": [
    {
      "id": "mireye-bearer-token",
      "type": "promptString",
      "description": "Mireye API bearer token. Optional alternative to `mireye-mcp login` for non-interactive hosts.",
      "password": true
    }
  ],
  "servers": {
    "earth": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "mireye-mcp@0.3.0"
      ],
      "env": {
        "MIREYE_BASE_URL": "<mireye-base-url>",
        "MIREYE_BEARER_TOKEN": "${input:mireye-bearer-token}",
        "MIREYE_TIMEOUT_S": "<mireye-timeout-s>",
        "MIREYE_MCP_CREDENTIALS_FILE": "/absolute/path/to/target"
      }
    }
  }
}
